package dev.lumora.launcher.core.mods;

import com.google.gson.reflect.TypeToken;
import dev.lumora.launcher.core.util.FileUtil;
import dev.lumora.launcher.core.util.Hashing;
import dev.lumora.launcher.core.util.Json;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

/**
 * Mods shipped inside the launcher distribution (only our own companion mod). bundled-mods.json maps
 * file name to SHA-512 and is generated by the Gradle build, so a tampered or truncated file is detected.
 */
public final class BundledMods {
    public static final String INDEX = "bundled-mods.json";

    private final Path dir;
    private final Map<String, String> hashes;

    public BundledMods(Path dir) throws IOException {
        this.dir = dir;
        Path index = dir.resolve(INDEX);
        if (!Files.isRegularFile(index)) {
            throw new IOException("Bundled component index missing: " + index
                    + ". The launcher installation is incomplete - please reinstall.");
        }
        Map<String, String> parsed = Json.GSON.fromJson(Files.readString(index),
                new TypeToken<Map<String, String>>() { }.getType());
        if (parsed == null) {
            throw new IOException("Empty " + index);
        }
        this.hashes = Map.copyOf(parsed);
    }

    /** Locates the bundled directory: -Dlumora.bundledDir, else "bundled" next to the launcher jar's folder. */
    public static Path locate() {
        String prop = System.getProperty("lumora.bundledDir");
        if (prop != null && !prop.isBlank()) {
            return Path.of(prop);
        }
        try {
            Path jar = Path.of(BundledMods.class.getProtectionDomain().getCodeSource().getLocation().toURI());
            return jar.getParent().resolve("bundled");
        } catch (Exception e) {
            return Path.of("bundled");
        }
    }

    public Path verified(String fileName) throws IOException {
        String expected = hashes.get(fileName);
        if (expected == null) {
            throw new IOException("Bundled component " + fileName + " is not listed in " + INDEX);
        }
        Path file = FileUtil.resolveInside(dir, fileName);
        if (!Hashing.matches(file, Hashing.Expected.sha512(expected))) {
            throw new IOException("Bundled component " + fileName + " is missing or corrupt. Please reinstall the launcher.");
        }
        return file;
    }
}
